insert into public.sq_iq_items(id,bank_version,band,domain,payload) values('iq-1-1-logic-0-0',1,1,'logic','{"id":"iq-1-1-logic-0-0","domain":"logic","prompt":"Barcha romblar — qizil shakllar. Barcha qizil shakllar — ramkadagi shakllar. Qaysi xulosa albatta kelib chiqadi?","visual":{"kind":"sets","labels":["X","Y","Z"],"legend":["romblar","qizil shakllar","ramkadagi shakllar"]},"options":["Barcha ramkadagi shakllar — qizil shakllar.","Barcha romblar — ramkadagi shakllar.","Barcha ramkadagi shakllar — romblar.","Hech bir romblar — ramkadagi shakllar emas."],"answer":1,"explanation":"Birinchi to‘plam ikkinchisining, ikkinchisi uchinchisining ichida. Demak birinchisi uchinchiga kiradi; teskari yo‘nalish kafolatlanmaydi."}'::jsonb) on conflict(id) do nothing;
